# fn-11-6w4.1 Create Rust depth color module with presets and HSL interpolation

## Description
Create new Rust module for depth color calculations with 5 color presets and HSL interpolation.

## New File: `src-tauri/src/export/depth_colors.rs`

### Depth Preset Enum
```rust
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum DepthPreset {
    Thermal,    // Blue (#00bfff) → Red (#ff4444)
    Ocean,      // Cyan (#00ffff) → Dark Blue (#0000aa)
    Terrain,    // Green (#00ff00) → Brown (#8b4513)
    Grayscale,  // White (#ffffff) → Black (#000000)
    Accessible, // Yellow (#fde047) → Purple (#7c3aed) - Viridis-inspired
}

impl Default for DepthPreset {
    fn default() -> Self {
        Self::Thermal
    }
}
```

### Preset Colors Struct
```rust
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DepthPresetColors {
    pub shallow: String,
    pub deep: String,
}

impl DepthPreset {
    pub fn colors(&self) -> DepthPresetColors {
        match self {
            Self::Thermal => DepthPresetColors {
                shallow: "#00bfff".to_string(),
                deep: "#ff4444".to_string(),
            },
            Self::Ocean => DepthPresetColors {
                shallow: "#00ffff".to_string(),
                deep: "#0000aa".to_string(),
            },
            Self::Terrain => DepthPresetColors {
                shallow: "#00ff00".to_string(),
                deep: "#8b4513".to_string(),
            },
            Self::Grayscale => DepthPresetColors {
                shallow: "#ffffff".to_string(),
                deep: "#000000".to_string(),
            },
            Self::Accessible => DepthPresetColors {
                shallow: "#fde047".to_string(),
                deep: "#7c3aed".to_string(),
            },
        }
    }
}
```

### HSL Interpolation (Shortest Hue Path)
```rust
/// Convert hex color to HSL
fn hex_to_hsl(hex: &str) -> (f64, f64, f64) {
    // Parse hex to RGB
    let hex = hex.trim_start_matches('#');
    let r = u8::from_str_radix(&hex[0..2], 16).unwrap_or(0) as f64 / 255.0;
    let g = u8::from_str_radix(&hex[2..4], 16).unwrap_or(0) as f64 / 255.0;
    let b = u8::from_str_radix(&hex[4..6], 16).unwrap_or(0) as f64 / 255.0;

    // RGB to HSL conversion
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let l = (max + min) / 2.0;

    if (max - min).abs() < f64::EPSILON {
        return (0.0, 0.0, l);
    }

    let d = max - min;
    let s = if l > 0.5 { d / (2.0 - max - min) } else { d / (max + min) };

    let h = if (max - r).abs() < f64::EPSILON {
        ((g - b) / d + if g < b { 6.0 } else { 0.0 }) / 6.0
    } else if (max - g).abs() < f64::EPSILON {
        ((b - r) / d + 2.0) / 6.0
    } else {
        ((r - g) / d + 4.0) / 6.0
    };

    (h * 360.0, s, l)
}

/// Convert HSL to hex color
fn hsl_to_hex(h: f64, s: f64, l: f64) -> String {
    // ... HSL to RGB to hex conversion
}

/// Interpolate between two colors using shortest hue path
pub fn get_depth_color(
    depth: f64,
    min_depth: f64,
    max_depth: f64,
    preset: DepthPreset,
) -> String {
    // Handle edge cases
    if (max_depth - min_depth).abs() < f64::EPSILON || depth.is_nan() {
        return preset.colors().shallow;
    }

    // Clamp and normalize
    let t = ((depth - min_depth) / (max_depth - min_depth)).clamp(0.0, 1.0);

    let colors = preset.colors();
    let (h1, s1, l1) = hex_to_hsl(&colors.shallow);
    let (h2, s2, l2) = hex_to_hsl(&colors.deep);

    // Shortest hue path interpolation
    let mut dh = h2 - h1;
    if dh > 180.0 {
        dh -= 360.0;
    } else if dh < -180.0 {
        dh += 360.0;
    }

    let h = (h1 + dh * t).rem_euclid(360.0);
    let s = s1 + (s2 - s1) * t;
    let l = l1 + (l2 - l1) * t;

    hsl_to_hex(h, s, l)
}
```

